begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir fixtures/costing-salon.inc
select is(pg_temp.cost_policy('c5000000-0000-4000-8000-000000000201','PERCENT_NET_OF_TAX',1000)#>>'{data,status}','SAVED','10 percent net policy before completion');
select is(pg_temp.costing(jsonb_build_object('type','ASSIGN','mutation_id',gen_random_uuid(),'id','c5000000-0000-4000-8000-000000000501','staff_user_id','b4000000-0000-4000-8000-000000000021','policy_id','c5000000-0000-4000-8000-000000000201','scope','DEFAULT_SERVICE','service_id',null,'category',null,'effective_from',statement_timestamp(),'effective_until',null,'reason','Authoritative performer assignment'))#>>'{data,status}','SAVED','real active staff receives service default');
select pg_temp.transition_finance('e5000000-0000-4000-8000-000000000811',1,'ARRIVED');
