select is((select amount_minor from public.commission_accruals where charge_id='c5000000-0000-4000-8000-000000000301'),10000::bigint,'10 percent of net 100000 exact');
select is((select staff_user_id::text from public.commission_accruals where charge_id='c5000000-0000-4000-8000-000000000301'),'b4000000-0000-4000-8000-000000000021','performed_by authoritative staff snapshot');
select is(pg_temp.cost_policy('c5000000-0000-4000-8000-000000000201','PERCENT_GROSS',2000,null,1)#>>'{data,status}','SAVED','next policy version affects future completion');
select is((select policy_version from public.commission_accruals where charge_id='c5000000-0000-4000-8000-000000000301'),1::bigint,'historical policy remains version one');
select is((select amount_minor from public.commission_accruals where charge_id='c5000000-0000-4000-8000-000000000301'),10000::bigint,'policy changes never rewrite commission');
select pg_temp.transition_finance('e5000000-0000-4000-8000-000000000812',1,'ARRIVED');
select pg_temp.transition_finance('e5000000-0000-4000-8000-000000000812',2,'IN_SERVICE');
select pg_temp.transition_finance('e5000000-0000-4000-8000-000000000812',3,'COMPLETED');
select is(pg_temp.charge_appointment('c5000000-0000-4000-8000-000000000302','e5000000-0000-4000-8000-000000000812')#>>'{data,status}','SAVED','future completion posts new version');
select is((select amount_minor from public.commission_accruals where charge_id='c5000000-0000-4000-8000-000000000302'),24000::bigint,'20 percent gross 120000 exact');
select is((select policy_version from public.commission_accruals where charge_id='c5000000-0000-4000-8000-000000000302'),2::bigint,'future version retained');
select is(pg_temp.cost_policy('c5000000-0000-4000-8000-000000000202','FIXED_AMOUNT',null,'5000')#>>'{data,status}','SAVED','fixed policy supported');
select is(pg_temp.costing(jsonb_build_object('type','ASSIGN','mutation_id',gen_random_uuid(),'id','c5000000-0000-4000-8000-000000000502','staff_user_id','b4000000-0000-4000-8000-000000000021','policy_id','c5000000-0000-4000-8000-000000000202','scope','SERVICE','service_id','e5000000-0000-4000-8000-000000000801','category',null,'effective_from',statement_timestamp(),'effective_until',null,'reason','Exact service precedence'))#>>'{data,status}','SAVED','exact service beats domain default');
select is(pg_temp.costing(jsonb_build_object('type','ASSIGN','mutation_id',gen_random_uuid(),'id',gen_random_uuid(),'staff_user_id','b4000000-0000-4000-8000-000000000021','policy_id','c5000000-0000-4000-8000-000000000202','scope','SERVICE','service_id','e5000000-0000-4000-8000-000000000801','category',null,'effective_from',statement_timestamp(),'effective_until',null,'reason','Ambiguous duplicate')) ->>'code','COMMISSION_ASSIGNMENT_OVERLAP','same precedence overlapping assignment rejected');
select pg_temp.book_finance('e5000000-0000-4000-8000-000000000813','2026-10-22T10:00');
select pg_temp.transition_finance('e5000000-0000-4000-8000-000000000813',1,'ARRIVED');
select pg_temp.transition_finance('e5000000-0000-4000-8000-000000000813',2,'IN_SERVICE');
select pg_temp.transition_finance('e5000000-0000-4000-8000-000000000813',3,'COMPLETED');
select pg_temp.charge_appointment('c5000000-0000-4000-8000-000000000303','e5000000-0000-4000-8000-000000000813');
select is((select amount_minor from public.commission_accruals where charge_id='c5000000-0000-4000-8000-000000000303'),5000::bigint,'fixed exact service wins');
select is(pg_temp.cost_policy('c5000000-0000-4000-8000-000000000202','FIXED_AMOUNT',null,'1000000',1)#>>'{data,status}','SAVED','future fixed policy larger than basis');
select pg_temp.book_finance('e5000000-0000-4000-8000-000000000814','2026-10-23T10:00');
select pg_temp.transition_finance('e5000000-0000-4000-8000-000000000814',1,'ARRIVED');
select pg_temp.transition_finance('e5000000-0000-4000-8000-000000000814',2,'IN_SERVICE');
select pg_temp.transition_finance('e5000000-0000-4000-8000-000000000814',3,'COMPLETED');
select pg_temp.charge_appointment('c5000000-0000-4000-8000-000000000304','e5000000-0000-4000-8000-000000000814');
select is((select amount_minor from public.commission_accruals where charge_id='c5000000-0000-4000-8000-000000000304'),100000::bigint,'fixed commission capped at eligible net revenue');
select pg_temp.finance_payment('PAYMENT','120000','c5000000-0000-4000-8000-000000000311','[{"charge_id":"c5000000-0000-4000-8000-000000000301","amount_minor":"120000"}]');
select pg_temp.finance(jsonb_build_object('type','REFUND','mutation_id',gen_random_uuid(),'id','c5000000-0000-4000-8000-000000000312','original_payment_id','c5000000-0000-4000-8000-000000000311','amount_minor','40000','occurred_at',statement_timestamp(),'reason','First eligible revenue refund'));
select pg_temp.finance(jsonb_build_object('type','REFUND','mutation_id',gen_random_uuid(),'id','c5000000-0000-4000-8000-000000000313','original_payment_id','c5000000-0000-4000-8000-000000000311','amount_minor','40000','occurred_at',statement_timestamp(),'reason','Second eligible revenue refund'));
set constraints profitability_refund_posted immediate;
select is((select sum(amount_minor) from public.commission_adjustments),(-6667)::numeric,'cumulative refund residual exactly 6667');
select is((select amount_minor from public.commission_adjustments where source_document_id='c5000000-0000-4000-8000-000000000313'),(-3334)::bigint,'last adjustment carries rounding residual');
select is(pg_temp.costing_read('{"charge_id":"c5000000-0000-4000-8000-000000000301"}')#>>'{data,items,0,commission_minor}','3333','remaining commission from immutable adjustments');
select pg_temp.finance(jsonb_build_object('type','REVERSAL','mutation_id',gen_random_uuid(),'id',gen_random_uuid(),'document_id','c5000000-0000-4000-8000-000000000302','reason','Administrative charge correction'));
select is(pg_temp.costing_read('{"charge_id":"c5000000-0000-4000-8000-000000000302"}')#>>'{data,items,0,net_revenue_minor}','0','reversal compensates full revenue');
select is(pg_temp.costing_read('{"charge_id":"c5000000-0000-4000-8000-000000000302"}')#>>'{data,items,0,commission_minor}','0','reversal compensates accrual');
select is((select count(*) from public.commission_accruals),4::bigint,'original accruals remain immutable');
reset role;
update public.salon_staff set version=version+1,active=false where membership_id='b4000000-0000-4000-8000-000000000111';
set local role authenticated;
select is((select count(*) from public.commission_accruals),4::bigint,'staff deactivation retains all commission history');
select * from finish();rollback;
